import java.util.*; import java.io.*; public class Main { public static long gcd(long a, long b) { while (b > 0) { a %= b; long temp = a; a = b; b = temp; } return a; } public static void main(String[] args) throws IOException { BufferedReader br = new BufferedReader(new InputStreamReader(System.in)); PrintWriter out = new PrintWriter(System.out); int t = Integer.parseInt(br.readLine()); while (t-- > 0) { int n = Integer.parseInt(br.readLine()); long[] a = new long[n]; StringTokenizer st = new StringTokenizer(br.readLine()); for (int i = 0; i < n; i++) a[i] = Long.parseLong(st.nextToken()); if (n == 1) { out.println(1); continue; } long[] pref = new long[n]; long[] suff = new long[n]; pref[0] = a[0]; for (int i = 1; i < n; i++) pref[i] = gcd(pref[i - 1], a[i]); suff[n - 1] = a[n - 1]; for (int i = n - 2; i >= 0; i--) suff[i] = gcd(suff[i + 1], a[i]); long minNotes = Long.MAX_VALUE; for (int i = 0; i < n; i++) { long currentGcd; if (i == 0) currentGcd = suff[1]; else if (i == n - 1) currentGcd = pref[n - 2]; else currentGcd = gcd(pref[i - 1], suff[i + 1]); long currentSum = 0; for (int j = 0; j < n; j++) { if (i == j) currentSum += 1; else currentSum += (a[j] / currentGcd); } minNotes = Math.min(minNotes, currentSum); } out.println(minNotes); } out.flush(); out.close(); } }